const body = $('Webhook: Wishlist Text In').item.json.body || {};
const text = (body.text || '').toString().trim();
const evidenceId = body.evidence_id || ('demo-' + Date.now() + '-' + Math.floor(Math.random()*10000));
return [{
  json: {
    text,
    evidence_id: evidenceId,
    systemPrompt: $json.systemPrompt
  }
}];

const httpNode = $('Groq: Classify (gpt-oss-20b)').item.json;
let parsed;
let valid = false;
let errorMsg = '';
try {
  const raw = httpNode.choices[0].message.content;
  parsed = JSON.parse(raw);
  const requiredKeys = ['evidence_id','is_relevant','primary_barrier','inferred_segment','workaround_observed','confidence_score'];
  const allowedBarriers = ['fit_size','price_certainty','occasion_styling','quality_trust','availability_decay','timing_forgetting','bookmark_not_intent','other','not_relevant'];
  const hasAllKeys = requiredKeys.every(k => Object.prototype.hasOwnProperty.call(parsed, k));
  const barrierOk = allowedBarriers.includes(parsed.primary_barrier);
  valid = hasAllKeys && barrierOk && typeof parsed.is_relevant === 'boolean';
  if (!valid) errorMsg = 'schema_mismatch';
} catch (e) {
  errorMsg = 'json_parse_failed: ' + e.message;
}
return [{
  json: {
    valid,
    parsed: parsed || null,
    errorMsg,
    evidence_id: $('Normalize Input').item.json.evidence_id
  }
}];

